package com.campus.lostfound.config; import com.campus.lostfound.service.PortalUserDetailsService; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; @Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain filterChain(HttpSecurity http,PortalUserDetailsService uds)throws Exception{return http.userDetailsService(uds).authorizeHttpRequests(a->a.requestMatchers("/","/login","/register","/css/**","/js/**","/images/**","/uploads/**","/error").permitAll().requestMatchers("/admin/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/dashboard",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout").permitAll()).build();} }